changeSet.sql:
CREATE OR REPLACE FUNCTION sum_total_amount_without_discounts_OBM_confirmed_quantity() RETURNS TRIGGER AS $orders$ BEGIN IF ((TG_OP = 'UPDATE' OR TG_OP = 'INSERT') AND (old.confirmed_quantity is not null or new.confirmed_quantity is not null ) ) THEN UPDATE orders o SET sum_total_amount_without_discounts = (SELECT sum(obm.confirmed_quantity * b.full_price) FROM order_bag_mapping obm INNER JOIN bag b on obm.bag_id = b.id WHERE order_id = o.id) WHERE o.id = old.order_id OR o.id = new.order_id; RETURN NEW; END IF; RETURN NEW; END $orders$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION sum_total_amount_without_discounts_OBM_exported_quantity() RETURNS TRIGGER AS $orders$ BEGIN IF ((TG_OP = 'UPDATE' OR TG_OP = 'INSERT') AND (old.exported_quantity is not null or new.exported_quantity is not null )) THEN UPDATE orders o SET sum_total_amount_without_discounts = (SELECT sum(obm.exported_quantity * b.full_price) FROM order_bag_mapping obm INNER JOIN bag b on obm.bag_id = b.id WHERE order_id = o.id) WHERE o.id = old.order_id OR o.id = new.order_id; RETURN NEW; END IF; RETURN NEW; END $orders$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS insert_update_order_bag_mapping_confirmed_quantity ON order_bag_mapping; DROP TRIGGER IF EXISTS insert_update_order_bag_mapping_exported_quantity ON order_bag_mapping;
CREATE TRIGGER insert_update_order_bag_mapping_confirmed_quantity AFTER UPDATE OF confirmed_quantity on order_bag_mapping FOR EACH ROW EXECUTE PROCEDURE sum_total_amount_without_discounts_OBM_confirmed_quantity();
CREATE TRIGGER insert_update_order_bag_mapping_exported_quantity AFTER UPDATE OF exported_quantity on order_bag_mapping FOR EACH ROW EXECUTE PROCEDURE sum_total_amount_without_discounts_OBM_exported_quantity(); /
